// Generated by scripts/generate-locales.mjs; edit the canonical content sources.
export default {"heading":"Cuộc đời, sự nghiệp và di sản","introduction":"Từ giảng đường đến quản lý nhà nước, từ nghiên cứu chính sách đến xây dựng các tổ chức nghề nghiệp: khám phá cuộc đời và những đóng góp của người sáng lập ICUE qua tám chương.","readerHint":"Mở từng chương hoặc đọc lần lượt bằng nút Tiếp tục.","back":"Quay lại","next":"Tiếp tục","complete":"Đọc xong","completed":"Đã đọc xong","counter":"Chương {current} / {total}","sourceHref":"https://nguoidothi.net.vn/nghi-ve-mot-nguoi-cong-hien-21097.html","source":"Nghĩ về một người cống hiến · 30.11.2019","photoEvents":{"2017":"Phỏng vấn truyền hình trên VTV1","2018":"Cuộc họp cùng các đồng nghiệp biên tập"},"chapters":[{"id":"life","title":"Cuộc đời và quê hương","period":"1931–2018","heading":"Một cuộc đời gắn với sự phát triển đô thị Việt Nam","paragraphs":["TS. Phạm Sỹ Liêm sinh năm 1931 tại Diễn Thành, Diễn Châu, Nghệ An. Là kỹ sư xây dựng, nhà khoa học và nhà quản lý, ông trải qua nhiều lĩnh vực công tác: giảng dạy đại học, quản lý nhà nước, nghiên cứu khoa học và thành lập các tổ chức chuyên môn.","Sự nghiệp của ông gắn với những vấn đề nền tảng của đô thị: nhà ở, đất đai, hạ tầng công cộng, quy hoạch và quản trị. Qua từng giai đoạn, ông tiếp tục tìm kiếm những cải cách giúp tri thức chuyên môn đóng góp thiết thực cho sự phát triển.","Ông qua đời ngày 30 tháng 11 năm 2018, hưởng thọ 87 tuổi, hay 88 tuổi theo cách tính tuổi truyền thống. Di sản để lại kết nối giáo dục kỹ thuật, kinh nghiệm công vụ, nghiên cứu chính sách độc lập và những tổ chức tiếp tục hoạt động sau ông, trong đó có ICUE."],"photoEvents":[]},{"id":"education","title":"Giảng dạy và đào tạo kỹ sư","period":"1958–1963","heading":"Góp phần đặt nền móng cho đào tạo bê tông cốt thép","paragraphs":["Trong những năm 1950–1960, ông giảng dạy kỹ thuật xây dựng và góp phần hình thành việc đào tạo chuyên ngành bê tông cốt thép tại Đại học Bách khoa Hà Nội. Tư liệu lịch sử của ngành xây dựng trong nhà trường ghi nhận đóng góp của ông trong việc đưa môn học này vào giảng dạy từ năm học 1958–1959.","Tháng 10 năm 1959, ông được bổ nhiệm làm Trưởng Bộ môn Bê tông cốt thép đầu tiên. Đây là một dấu mốc quan trọng trong sự nghiệp đào tạo và xây dựng nền tảng học thuật của ông.","Năm 1963, ông bắt đầu học sau đại học tại Liên Xô, sau đó tiếp tục đảm nhiệm vai trò lãnh đạo học thuật. Kinh nghiệm giảng dạy và nghiên cứu kỹ thuật trở thành một phần nền tảng cho những công việc quản lý và nghiên cứu đô thị về sau."],"photoEvents":[]},{"id":"public-service","title":"Công vụ và tổ chức nghề nghiệp","period":"Từ năm 1982","heading":"Từ quản lý nhà nước đến xây dựng cộng đồng chuyên môn","paragraphs":["Trong sự nghiệp quản lý nhà nước, TS. Phạm Sỹ Liêm từng giữ chức Thứ trưởng Bộ Xây dựng và Phó Chủ tịch Ủy ban nhân dân thành phố Hà Nội. Những vị trí này gắn kết chuyên môn kỹ thuật của ông với các vấn đề quản lý xây dựng, hạ tầng và phát triển đô thị.","Từ năm 1982, ông là Chủ tịch sáng lập Tổng hội Xây dựng Việt Nam, lãnh đạo ba nhiệm kỳ đầu tiên và về sau tiếp tục giữ vai trò Phó Chủ tịch Tổng hội.","Đóng góp của ông không chỉ nằm ở chức danh lãnh đạo. Qua nhiều thập kỷ, ông tham gia xây dựng cơ cấu tổ chức, phát triển hoạt động nghiên cứu và tăng cường tiếng nói chuyên môn của Tổng hội. Việc xây dựng các thiết chế nghề nghiệp là một phần quan trọng trong những thành tựu mà đồng nghiệp ghi nhận ở ông."],"photoEvents":[]},{"id":"institutes","title":"Xây dựng các viện nghiên cứu","period":"1999 · 2013","heading":"Hai tổ chức dành cho nghiên cứu đô thị và tư vấn chính sách","paragraphs":["Trong những năm 1990–2000, ông mở rộng nghiên cứu về quản trị đô thị, hạ tầng và chính sách xây dựng. Năm 1999, ông sáng lập Viện Nghiên cứu Đô thị và Phát triển Hạ tầng, tạo một cơ sở chuyên môn dành cho những lĩnh vực này.","Năm 2013, ông tiếp tục sáng lập Viện Nghiên cứu Kinh tế Xây dựng và Đô thị — ICUE — và trở thành Viện trưởng đầu tiên. Đây là một bước tiếp nối trong hành trình xây dựng các tổ chức kết nối nghiên cứu với tư vấn chính sách và thực tiễn phát triển.","Hai viện nghiên cứu thể hiện sự quan tâm lâu dài của ông đối với quy hoạch đô thị, kinh tế xây dựng và hạ tầng. Với ICUE, di sản của người sáng lập nằm ở sự kết hợp giữa nền tảng kỹ thuật, kinh nghiệm quản lý công và tinh thần nghiên cứu độc lập."],"photoEvents":[]},{"id":"policy","title":"Góp ý chính sách và đối thoại đô thị","period":"2012–2017","heading":"Những đóng góp cụ thể về đất đai, quy hoạch và thể chế","paragraphs":["Thông qua sách, đề tài nghiên cứu, hội thảo và phỏng vấn, ông thường xuyên trao đổi về nhà ở, quản lý đất đai, hạ tầng công cộng và quản trị đô thị. Ông cũng nêu những bất cập trong quy hoạch và thực thi chính sách, coi việc phản biện là một phần của đóng góp chuyên môn.","Năm 2012, ông gửi những ý kiến phản biện chi tiết đối với dự thảo Luật Đất đai qua VCCI. Nội dung tập trung vào thu hồi đất, quyền tài sản và tính minh bạch, cho thấy mối quan tâm của ông đến cách các quy định tác động đến đời sống và sự phát triển.","Trong các năm 2016–2017, ông tham gia thảo luận công khai về Luật Quy hoạch, đề xuất tăng cường sự phối hợp trong quy hoạch quốc gia và thúc đẩy cải cách thể chế. Những đóng góp này được ghi nhận qua các hồ sơ góp ý chính sách, bên cạnh các bài tưởng nhớ về ông.","Năm 2017, ông xuất hiện trong một cuộc phỏng vấn truyền hình trên VTV1. Bức ảnh tư liệu dưới đây ghi lại cuộc phỏng vấn này."],"photoEvents":["2017"]},{"id":"editorial","title":"Người Đô Thị và công việc biên tập","period":"2006–2018","heading":"Một diễn đàn về đô thị và chất lượng sống","paragraphs":["Năm 2006, TS. Phạm Sỹ Liêm đồng sáng lập Người Đô Thị, một tạp chí dành cho các vấn đề đô thị, đồng thời đảm nhiệm vai trò Chủ tịch Hội đồng cố vấn chuyên môn của tạp chí.","Ấn phẩm trở thành một diễn đàn trao đổi về chính sách đô thị và chất lượng sống. Công việc ở Người Đô Thị mở thêm một hướng đóng góp của ông: đưa những vấn đề chuyên môn ra thảo luận cùng công chúng, bên cạnh nghiên cứu và hoạt động trong các tổ chức nghề nghiệp.","Ông tiếp tục gắn bó về chuyên môn với tạp chí cho đến khi qua đời. Bức ảnh năm 2018 ghi lại ông trong cuộc họp cùng các đồng nghiệp biên tập, một trong những cuộc họp biên tập cuối cùng của ông được ghi lại."],"photoEvents":["2018"]},{"id":"scholarship","title":"Nghiên cứu đến những năm cuối đời","period":"Tháng 9.2018","heading":"Tân kinh tế học thể chế — công trình ở tuổi 87","paragraphs":["Trong các năm 2017–2018, dù tuổi đã cao, ông vẫn tiếp tục nghiên cứu và tư vấn cho các tổ chức chuyên môn. Niềm say mê học thuật không dừng lại khi ông đã trải qua nhiều cương vị quản lý cấp cao.","Tháng 9 năm 2018, ông xuất bản Tân kinh tế học thể chế, công trình học thuật lớn cuối cùng của mình. Cuốn sách tìm hiểu mối quan hệ giữa thể chế và phát triển kinh tế, tiếp nối sự quan tâm lâu dài của ông đối với cải cách và quản trị.","Được xuất bản khi tác giả 87 tuổi, cuốn sách được ghi nhận đã tham khảo hơn 200 tài liệu nước ngoài, cùng các nghiên cứu và văn bản chính sách của Việt Nam. Công trình này cho thấy tinh thần tiếp tục học hỏi và lao động trí tuệ của ông trong năm cuối đời."],"photoEvents":[]},{"id":"legacy","title":"Con người và ký ức đồng nghiệp","period":"Ký ức tại lễ tưởng nhớ năm 2019","heading":"Liêm chính, chiều sâu tri thức và sức làm việc","paragraphs":["Đồng nghiệp nhớ đến ông như một học giả tiếp tục học hỏi ngay cả sau khi đã giữ những chức vụ quản lý cấp cao. Các bài viết về ông ghi nhận khả năng sử dụng bốn ngoại ngữ: tiếng Anh, tiếng Pháp, tiếng Nga và tiếng Trung.","Tại một sự kiện tưởng nhớ năm 2019, Chủ tịch Tổng hội Trần Ngọc Hùng kể lại rằng mỗi khi đi nước ngoài, TS. Phạm Sỹ Liêm thường tìm đến các hiệu sách. Ông có một thư viện cá nhân phong phú, đọc rộng nhiều lĩnh vực và còn yêu thích cả tiểu thuyết võ hiệp.","Viện sĩ Phạm Hồng Giang nhìn nhận di sản của ông qua ba phẩm chất: sự liêm chính, chiều sâu tri thức và năng lực làm việc đặc biệt. Đây là những đánh giá, ký ức của đồng nghiệp, giúp phác họa con người phía sau các chức danh và công trình.","Bài viết Nghĩ về một người cống hiến năm 2019 mang đến một góc nhìn gần gũi hơn qua lời kể của người đã làm việc với ông trong nhiều thập kỷ. Đối với ICUE, sự kết hợp giữa đào tạo kỹ sư, công vụ, nghiên cứu độc lập, xây dựng tổ chức và học tập suốt đời là di sản bền lâu của người sáng lập."],"photoEvents":[]}],"nguoiDoThi":"https://nguoidothi.net.vn/","remembrance":"https://nguoidothi.net.vn/nghi-ve-mot-nguoi-cong-hien-21097.html"}
